globalStyles.embedded:
body { background-color: #fff; padding: 0 0 40px; font-family: "Helvetica", sans-serif; font-weight: 400; line-height: 1.6em; text-align: center; color: #465546; }
#header { margin-bottom: 72px; }
#content { margin: 0 auto; max-width: 600px; text-align: left; }
#content p.viewin a { color: #999; }
#content p.viewin a:hover { color: #465546; }
img { padding: 0; max-width: 100%; height: auto; }
img#logo { margin: 0; padding: 0; max-width: 300px; height: auto; }
a { color: #DC4B4B; text-decoration: none; }
a:hover { text-decoration: underline !important; }
h1, h2, h3, h4 { font-family: "Lora", serif; }
h1 { margin: 12px 0 0; padding: 10px 0; float: right; line-height: 100%; font-weight: normal; border-bottom: 1px solid; }
h2 { margin: 0; padding: 48px 0 0; font-size: 36px; line-height: 1.2em; font-weight: 400; }
p, ul { font-size: 18px; }
p { line-height: 1.6em; }
blockquote { margin: 40px 0; padding: 0 0 0 20px; border-left: 1px solid #B7E2D8; }
blockquote p { font-family: "Lora", serif; font-size: 17px; line-height: 1.6em; }
p.legend { margin: 5px 0 0; padding: 0; font-size: 12px; text-align: center; }
.highlight { background: #B7E2D8; }
.divider { text-align: center; }
strong.caps { text-transform: uppercase; font-weight: bold; letter-spacing: .05em; font-size: 85%; }
ul { margin: 24px 0 0; padding: 0; }
li { margin: 0; padding: 12px 0; list-style: none; border-top: 1px solid #B7E2D8; line-height: 1.4em; }
li em { font-style: normal; }
#footer { margin-top: 72px; }
p.subs { padding-top: 30px; text-align: center; color: #999; }
p.subs span { font-style: italic; font-size: .8888em; }
.subs a { -webkit-appearance: none; -moz-appearance: none; background: #DC4B4B; border: none; border-radius: .3rem; color: #fff; cursor: pointer; display: inline-block; font-size: .8888em; font-weight: 600; line-height: 1; margin: 5px 0 0; padding: 1.175em 1.75em; text-align: center; text-decoration: none; transition: opacity .15s linear; }
@media only screen and (max-width:480px) {
  body { width: 95% !important; min-width: 95% !important; }
  h1 { float: none; display: block; width: 100%; margin-top: 10px !important; margin-right: 10px; margin-bottom: 20px; }
  #content { margin-right: 10px !important; margin-left: 10px !important; }
  p, ul { font-size: 20px; line-height: 1.6em; }
  blockquote p { font-size: 18px; line-height: 1.6em; }
  img { max-width: 100%; }
  img#logo { margin: 0; padding: 0; width: 200px; }
  table#canspamBar td { font-size: 14px !important; }
  table#canspamBar td a { display: block !important; margin-top: 10px !important; }
}
